    ('cc5fb86d-5a12-4ff9-85dc-5c02534e9d7a'::uuid, 'period_name', '500 - 1000 AD', NULL, 'fields-wd3-2026-10-02b-s010-rollback:cc5fb86d-5a12-4ff9-85dc-5c02534e9d7a:period_name', 'rollback of fields-wd3-2026-10-02b-s010: period_name None restored on Wat''s Dyke', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(820) = ''500 - 1000 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0117)", "decision": "replace", "status": "MISSING", "reasoning": "The date is disputed (sub-Roman to early 9th century), but the article reports 2006 excavations dating it 792-852 and tentatively places construction in the 820s; the earlier 411-561 date is said to belong to a preceding earthwork. 820 is given as the hedged start.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)"}]'::jsonb),
